#pragma once

#include <string>

#include "imgui.h"

class Panel
{
public:
	explicit Panel(std::string title) : title(std::move(title)) {}
	virtual ~Panel() = default;

	// Called by App once per frame. Wraps DrawContent() in Begin/End.
	void Render()
	{
		if (!isOpen)
			return;

		if (ImGui::Begin(title.c_str(), &isOpen))
			DrawContent();
		ImGui::End();
	}

	// Called once per frame before Render(), for non-UI logic (optional).
	virtual void Update() {}

	const std::string& GetTitle() const { return title; }
	bool IsOpen() const { return isOpen; }
	void SetOpen(bool open) { isOpen = open; }

protected:
	// Put your ImGui widgets here.
	virtual void DrawContent() = 0;

private:
	std::string title;
	bool isOpen = true;
};
